"""Public export dispatcher.

All formats funnel through :func:`src.exporter.export_rows`; this module
re-exports the legacy entry points alongside :func:`export`.
"""

from . import exporter
from .csv_exporter import export_csv  # noqa: F401  (backwards-compatible name)
from .json_exporter import export_json  # noqa: F401  (backwards-compatible name)


def export(rows, format):
    """Serialize ``rows`` as ``format`` ('csv' or 'json'); ValueError otherwise."""
    return exporter.export_rows(rows, format)

